WITH exploded AS (SELECT id, service, log_ts, level, status_code, k, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS k, v), parsed AS (SELECT id, k, v, CAST((status_code & 2) != 0 AS INT) AS flag_bit2, SHIFTRIGHT(status_code, 2) AS status_code_high FROM exploded), scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY k ORDER BY flag_bit2 DESC, id, k) event_seq, DENSE_RANK() OVER (PARTITION BY k ORDER BY flag_bit2 NULLS FIRST) flag_bit2_dense_rank, NTILE(5) OVER (ORDER BY status_code_high, id, k) status_code_high_bucket, SUM(flag_bit2) OVER (PARTITION BY k ORDER BY status_code_high, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_flag_bit2, STDDEV_SAMP(status_code_high) OVER (PARTITION BY k) k_stddev_samp_status_code_high FROM parsed), with_windows AS (SELECT id, k, v, flag_bit2, status_code_high, event_seq, flag_bit2_dense_rank, status_code_high_bucket, running_flag_bit2, k_stddev_samp_status_code_high, LAST_VALUE(running_flag_bit2) IGNORE NULLS OVER w_hist last_known_running_flag_bit2, CUME_DIST() OVER (ORDER BY k_stddev_samp_status_code_high DESC) k_stddev_samp_status_code_high_cume_dist FROM scored WINDOW w_hist AS (PARTITION BY k ORDER BY status_code_high_bucket, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), metrics AS (SELECT id, k, v, flag_bit2, status_code_high, event_seq, flag_bit2_dense_rank, status_code_high_bucket, running_flag_bit2, k_stddev_samp_status_code_high, last_known_running_flag_bit2, k_stddev_samp_status_code_high_cume_dist, AVG(k_stddev_samp_status_code_high) OVER (PARTITION BY k ORDER BY status_code_high, id, k ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) k_stddev_samp_status_code_high_avg_3, NTILE(4) OVER w_part status_code_high_bucket_2 FROM with_windows WINDOW w_part AS (ORDER BY status_code_high, id, k)), enriched AS (SELECT id, k, v, flag_bit2, status_code_high, event_seq, flag_bit2_dense_rank, status_code_high_bucket, running_flag_bit2, k_stddev_samp_status_code_high, last_known_running_flag_bit2, k_stddev_samp_status_code_high_cume_dist, k_stddev_samp_status_code_high_avg_3, status_code_high_bucket_2, STDDEV_SAMP(flag_bit2_dense_rank) OVER (PARTITION BY k) k_stddev_samp_flag_bit2_dense_rank, STDDEV_SAMP(last_known_running_flag_bit2) OVER (PARTITION BY k) k_stddev_samp_last_known_running_flag_bit2, ROW_NUMBER() OVER (ORDER BY status_code_high_bucket_2 DESC, id, k) seq_no FROM metrics) SELECT k, CASE WHEN seq_no >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS seq_no_tier, CASE WHEN status_code_high >= 2 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_high_tier, COUNT(CASE WHEN k = 'version' THEN 1 END) AS version_count, SUM(CASE WHEN k = 'trace' THEN running_flag_bit2 ELSE 0 END) AS trace_running_flag_bit2, AVG(k_stddev_samp_last_known_running_flag_bit2) AS avg_k_stddev_samp_last_known_running_flag_bit2, PERCENT_RANK() OVER (PARTITION BY k ORDER BY SUM(CASE WHEN k = 'trace' THEN running_flag_bit2 ELSE 0 END) DESC) AS trace_running_flag_bit2_percent_rank FROM enriched GROUP BY k, CASE WHEN seq_no >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN status_code_high >= 2 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY version_count NULLS LAST;
